function interactRegion(r){if(r.locked)return{ok:false,reason:r.reason||(r.operation==='travel'?'This passage is sealed. Continue the region’s objectives.':'Defeat the nearby guardians first.')};if(r.completed)return{ok:false,reason:'Already completed.'};if(!canReachRegion(r)){if(setDestination(new T.Vector3(r.x,0,r.z))){pendingRegionInteraction=r.id;return{ok:true,approaching:r.name};}return{ok:false,reason:'That path is blocked.'};}pendingRegionInteraction=null;releaseInput();return{ok:network.send(r.operation,{id:r.id}),pending:true};}
