function renderRegionLabels(){const records=regionInteractions(),ids=new Set(records.map(r=>r.id));for(const[id,label]of regionLabels)if(!ids.has(id)){label.remove();regionLabels.delete(id);}for(const r of records){let label=regionLabels.get(r.id);if(!label){label=document.createElement('button');label.type='button';label.className='world-label npc-label';label.onclick=()=>{if(paused||backgrounded||state.ended)return;awaken();const result=interact(r.id);if(!result.ok)toast(result.reason);};$('world-labels').append(label);regionLabels.set(r.id,label);}label.textContent=regionActionName(r);const projected=new T.Vector3(r.x,2,r.z).project(camera);label.hidden=r.completed||distance(r,player.position)>11||projected.z>1||Math.abs(projected.x)>.94||Math.abs(projected.y)>.86;label.style.left=`${(projected.x*.5+.5)*innerWidth}px`;label.style.top=`${(-projected.y*.5+.5)*innerHeight}px`;}}
function renderHazards(){const hazards=lastSnapshot?.hazards||[],ids=new Set(hazards.map(h=>h.id));for(const[id,visual]of networkHazards)if(!ids.has(id)){removeObject(visual);networkHazards.delete(id);}for(const h of hazards){let visual=networkHazards.get(h.id);if(!visual){visual=new T.Group();visual.position.set(h.x,.14,h.z);const geometry=h.radius?new T.CircleGeometry(h.radius,48):new T.PlaneGeometry(h.w,h.d);const fill=new T.Mesh(geometry,new T.MeshBasicMaterial({color:0xe88a46,transparent:true,opacity:.2,side:T.DoubleSide,depthWrite:false}));fill.rotation.x=-Math.PI/2;visual.add(fill);const edge=new T.LineSegments(new T.EdgesGeometry(geometry),new T.LineBasicMaterial({color:0xffbf7a,transparent:true,opacity:.9}));edge.rotation.x=-Math.PI/2;visual.add(edge);visual.rotation.y=h.angle||0;scene.add(visual);networkHazards.set(h.id,visual);}const active=lastSnapshot.time>=h.activateAt;visual.children[0].material.opacity=active?.58:.12+.2*Math.max(0,Math.min(1,(lastSnapshot.time-h.start)/Math.max(.1,h.activateAt-h.start)));visual.children[0].material.color.set(active?0xff4932:0xe88a46);}}

function nearestEnemy(range=9){let best=null,dist=range;for(const e of enemies){if(e.dead)continue;const d=distance(player.position,e.model.position);if(d<dist){best=e;dist=d;}}return best;}
