window.addEventListener('pointerup',event=>{if(event.button===0)attackHeld=false;});window.addEventListener('pointercancel',()=>{attackHeld=false;});$('world').addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',event=>{if(event.defaultPrevented||!ready||!network?.connected||!$('loading').hidden)return;if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement||event.target instanceof HTMLSelectElement)return;const key=event.key.toLowerCase();if(rosterPicker?.open)return;if(key==='c'&&!event.repeat){openRoster();return;}if(event.target instanceof HTMLButtonElement&&[' ','enter'].includes(key))return;if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(key)&&key!=='tab')event.preventDefault();if(event.repeat&&['escape','1','2','3','h','j','m','f','i'].includes(key))return;if(key==='escape'){if(mapExpanded)toggleMap();else if(paused)closeModal();else showModal('pause');return;}if(key==='h'){paused?closeModal():showModal('help');return;}if(key==='j'){paused?closeModal():showModal('journal');return;}if(key==='m'){toggleMap();return;}if(key==='i'){paused?closeModal():showModal('inventory');return;}if(!ready||paused||backgrounded||state.ended||!network?.connected)return;keys.add(key);if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','1','2','3'].includes(key))awaken();if(key==='1')perform('dodge');if(key==='2')perform('nova');if(key==='3')perform('heal');if(key==='f'){awaken();const result=interact();if(!result.ok)toast(result.reason);}});window.addEventListener('keyup',event=>keys.delete(event.key.toLowerCase()));
function releaseInput({resetTouch=true}={}){keys.clear();attackHeld=false;moveTarget=null;movePath=[];lockedEnemy=null;pendingRegionInteraction=null;if(network){network.input={x:0,z:0,angle};network.send('input',network.input);}if(resetTouch)releaseJoystick();}
