 life.syncLoot(snapshot.loot);life.syncForage(snapshot.forage);environment.updateProgress?.(state);environment.sync?.(snapshot.interactions,state.discoveries);if(renderedMap==='overworld'){landmarks?.updateProgress?.(state);landmarks?.sync?.(snapshot.interactions,state.discoveries);}
 connectionStatus(`${snapshot.players.length} / 8 adventurers · ${classFor(state).name} ${me.slot+1}`,true);
 $('restart-vote').hidden=sessionMode==='single-player'||!snapshot.votes.length;$('restart-vote-text').textContent=`Restart the game? ${snapshot.votes.length} / ${snapshot.players.length} agree. All progress will reset.`;
 $('restart-yes').disabled=snapshot.votes.includes(snapshot.you);
 for(const event of snapshot.events)if(event.id>lastNetworkEvent){networkEvent(event);lastNetworkEvent=event.id;}
 if(state.level>oldLevel&&!changed){toast(`Oath strengthened · Level ${state.level}`);audio.play('levelup',.65);}if(state.ended&&!wasDead){dismissMainMenu();audio.play('death-player',.8);releaseInput();if(mapExpanded)toggleMapForDeath();showModal('death');}
 if(wasDead&&!state.ended||changed){dismissMainMenu();inventoryPreviews.hide();audio.pause(backgrounded,backgrounded);$('modal-shade').hidden=true;modalKind='';paused=false;mapExpanded=false;document.querySelector('.map-panel').classList.remove('expanded');player.rotation.z=0;player.position.y=0;}
 if(mainMenuOpen&&!rosterPicker?.open)titleScreen.updateSession(mainMenuSession());
 if(!state.classId&&!rosterPicker?.open)openRoster();
 if(modalKind==='npc'&&beforeServices!==JSON.stringify([state.gold,state.potions,state.forgeLevel,state.questAccepted,state.questRewarded,state.victory,state.bossLootClaimed,state.rookSupplies]))renderNpc();if(modalKind==='inventory'&&beforeInventory!==JSON.stringify([state.inventory,state.equipped]))renderInventory();if(modalKind==='inventory')updateInventoryResources($('modal-content').closest('.modal'),state,network.connected);updateUI();
